import { ROUTES } from '@vulcan-ai/frontend-shared/lib/src/app/constants/Routes';
import { useConfig } from '@vulcan-ai/frontend-shared/lib/src/commons/config';
import { useIntlResolver } from '@vulcan-ai/frontend-shared/lib/src/commons/i18n/useIntlResolver';
import { Redirect, useParams } from '@vulcan-ai/frontend-shared/lib/src/commons/route';
import { useRoute } from '@vulcan-ai/frontend-shared/lib/src/commons/route/hooks/useRoute';
import { Box } from '@vulcan-ai/vulcan-ui/lib/components/Box/Box';
import { Divider } from '@vulcan-ai/vulcan-ui/lib/components/Divider/Divider';
import { FlexBox } from '@vulcan-ai/vulcan-ui/lib/components/Flex/FlexBox';
import { Grid } from '@vulcan-ai/vulcan-ui/lib/components/Grid';
import { Tabs } from '@vulcan-ai/vulcan-ui/lib/components/Tabs';
import { styled } from '@vulcan-ai/vulcan-ui/lib/theme';
import React, { useState } from 'react';
import { FormattedMessage, useIntl } from 'react-intl';
import { ChartLevel, ChartSet, Role } from 'src/apps/common/__generated__/types';
import { AnalyticChartsGrid } from 'src/modules/Analytic/components/AnalyticChartsGrid';
import { ChartsLastUpdatedAtDate } from 'src/modules/Analytic/components/AnalyticsLastUpdatedAtDate/ChartsLastUpdatedAtDate';
import { AnalyticTrendsDateFilter } from 'src/modules/Analytic/components/AnalyticTrendsDateFilter';
import { AnalyticFilterProvider } from 'src/modules/Analytic/context/AnalyticFilter';
import { useGetChartsQuery } from 'src/modules/Analytic/hooks/useGetChartsQuery';
import { TeamMemberProjectsTable } from 'src/modules/Team/components/TeamMemberProjectsTable/TeamMemberProjectsTable';
import { useTeamContext } from 'src/modules/Team/context';
import { useGetTeamMemberDetailQuery } from 'src/modules/Team/hooks/useGetTeamMemberDetailQuery';
import {
  MainLayoutBreadcrumb,
  MainLayoutBreadcrumbItemLink,
  MainLayoutBreadcrumbTitle,
  NavbarPortalGate,
} from '../MainLayout';
import { UserProfile } from '../MainLayout/UserProfile/UserProfile';
import { UserProfileMenuPortalGate } from '../MainLayout/UserProfile/UserProfileMenuPortal';

const CHART_LEVEL_TO_ROLE = {
  [ChartLevel.TEAM_MEMBER_AS_REVIEWER]: Role.REVIEWER,
  [ChartLevel.TEAM_MEMBER_AS_LABELER]: Role.LABELER,
};

export default function TeamMemberAnalyticsPage() {
  const config = useConfig();
  const { formatMessage } = useIntl();
  const { construct } = useRoute();
  const { teamDetail } = useTeamContext();
  const { memberId } = useParams<{ memberId: string }>();
  const memberDetail = useGetTeamMemberDetailQuery(teamDetail.id, memberId);
  const [chartLevel, setChartLevel] = useState<ChartLevel>(ChartLevel.TEAM_MEMBER_AS_LABELER);
  const resolvedIntl = useIntlResolver({
    title: { messageId: memberDetail.data?.result.user?.displayName },
  });

  const { enableAnalytics, teamMemberAnalyticsTable, enableLabelingAgentSpanBased } = config.app.featureToggle;

  const { loading, data } = useGetChartsQuery(teamDetail.id, chartLevel, ChartSet.ELASTIC);
  const userId = memberDetail.data?.result.user?.id ?? null;

  const handleRoleChange = (_event: React.SyntheticEvent, role: ChartLevel) => {
    setChartLevel(role);
  };
  const userRole = CHART_LEVEL_TO_ROLE[chartLevel as keyof typeof CHART_LEVEL_TO_ROLE];

  const breadcrumbItems = [
    {
      item: (
        <MainLayoutBreadcrumbItemLink to={construct(ROUTES.TEAM_MEMBERS)}>
          <FormattedMessage id="team-members-page.title" />
        </MainLayoutBreadcrumbItemLink>
      ),
    },
    {
      item: <MainLayoutBreadcrumbTitle maxWidth="15vw">{resolvedIntl.title}</MainLayoutBreadcrumbTitle>,
    },
  ];

  if (memberDetail.error) {
    return <Redirect to={construct(ROUTES.TEAM_MEMBERS)} />;
  }

  const renderCharts = () => (
    <AnalyticChartsGrid
      chartsQuery={{ loading, data }}
      widgetProps={{
        teamId: teamDetail.id,
        userId,
        teamMemberId: enableLabelingAgentSpanBased ? memberId : undefined,
        height: 334,
        labeledBy: userRole,
      }}
    />
  );

  return (
    <AnalyticFilterProvider>
      <FlexBox p={3}>
        <NavbarPortalGate>
          <FlexBox alignItems="center" justifyContent="center">
            <MainLayoutBreadcrumb breadcrumbItems={breadcrumbItems} />
          </FlexBox>
          <FlexBox ml={3}>
            <ChartsLastUpdatedAtDate
              chartLevel={chartLevel}
              chartSet={ChartSet.ELASTIC}
              input={{ teamId: teamDetail.id, userId: userId }}
            />
          </FlexBox>
        </NavbarPortalGate>
        <UserProfileMenuPortalGate>
          <UserProfile />
        </UserProfileMenuPortalGate>

        <Grid container>
          <Grid item xs={12}>
            <RoleContainer p={3} alignItems="center" justifyContent="flex-start">
              <StyledTabs value={chartLevel} onChange={handleRoleChange}>
                <Tabs.Tab label={formatMessage({ id: 'common.labeler' })} value={ChartLevel.TEAM_MEMBER_AS_LABELER} />
                <Tabs.Tab label={formatMessage({ id: 'common.reviewer' })} value={ChartLevel.TEAM_MEMBER_AS_REVIEWER} />
              </StyledTabs>
            </RoleContainer>
          </Grid>
          {enableAnalytics && (
            <>
              <Grid item xs={12}>
                <AnalyticTrendsDateFilter />
              </Grid>
              {renderCharts()}
              <Grid item xs={12}>
                <DividerMargin>
                  <Divider />
                </DividerMargin>
              </Grid>
            </>
          )}
          {teamMemberAnalyticsTable && (
            <Grid item xs={12}>
              <Box p={3}>
                {userId && (
                  <TeamMemberProjectsTable
                    teamId={teamDetail.id}
                    userId={userId}
                    role={userRole}
                    key={`${teamDetail.id}-${userId}-${userRole}`}
                  />
                )}
              </Box>
            </Grid>
          )}
        </Grid>
      </FlexBox>
    </AnalyticFilterProvider>
  );
}

const RoleContainer = styled(FlexBox, { name: 'TeamMemberAnalyticsPage-RoleContainer' })(() => ({
  margin: 'auto',
}));

const DividerMargin = styled(Box, { name: 'TeamMemberAnalyticsPage-DividerMargin' })(() => ({
  margin: '12px 16px',
}));

const StyledTabs = styled(Tabs, { name: 'TeamMemberAnalyticsPage-StyledTabs' })(() => ({
  '& .Mui-selected': {
    backgroundColor: 'transparent !important',
  },
}));

