import { ROUTES } from '@vulcan-ai/frontend-shared/lib/src/app/constants/Routes';
import { useConfig } from '@vulcan-ai/frontend-shared/lib/src/commons/config';
import { getUrlParameter } from '@vulcan-ai/frontend-shared/lib/src/commons/helpers/getUrlParameter';
import { useMemoizedCallback } from '@vulcan-ai/frontend-shared/lib/src/commons/hooks/useMemoizedCallback';
import { useIntlResolver } from '@vulcan-ai/frontend-shared/lib/src/commons/i18n/useIntlResolver';
import { useHistory, useParams } from '@vulcan-ai/frontend-shared/lib/src/commons/route';
import { useRoute } from '@vulcan-ai/frontend-shared/lib/src/commons/route/hooks/useRoute';
import { useFeatureTrackingService } from '@vulcan-ai/frontend-shared/lib/src/modules/FeatureTracking/contexts/FeatureTrackingServiceContext';
import {
  FeatureTrackingAction,
  FeatureTrackingProperties,
} from '@vulcan-ai/frontend-shared/lib/src/modules/FeatureTracking/interfaces';
import { useActiveTeam } from '@vulcan-ai/frontend-shared/lib/src/modules/Team/hooks/useActiveTeam';
import { Button } from '@vulcan-ai/vulcan-ui/lib/components/Button/Button';
import { FlexBox } from '@vulcan-ai/vulcan-ui/lib/components/Flex/FlexBox';
import { Grid } from '@vulcan-ai/vulcan-ui/lib/components/Grid';
import { CircularProgress } from '@vulcan-ai/vulcan-ui/lib/components/ProgressIndicator/CircularProgress/CircularProgress';
import { Tabs } from '@vulcan-ai/vulcan-ui/lib/components/Tabs';
import { useToggle } from '@vulcan-ai/vulcan-ui/lib/helpers/useToggle';
import { EditIcon } from '@vulcan-ai/vulcan-ui/lib/icon/EditIcon';
import { styled } from '@vulcan-ai/vulcan-ui/lib/theme';
import React, { useCallback, useState } from 'react';
import { FormattedMessage, useIntl } from 'react-intl';
import { AnalyticChartsGrid } from 'src/modules/Analytic/components/AnalyticChartsGrid';
import { AnalyticTrendsDateFilter } from 'src/modules/Analytic/components/AnalyticTrendsDateFilter';
import { ChartsLastUpdatedAtDate } from 'src/modules/Analytic/components/AnalyticsLastUpdatedAtDate/ChartsLastUpdatedAtDate';
import { IAAForm } from 'src/modules/Analytic/components/IAAForm';
import { IAAWidgetContainer } from 'src/modules/Analytic/components/IAAWidgetContainer';
import { ProjectEvaluationMetricsWidget } from 'src/modules/Analytic/components/ProjectEvaluationMetrics/ProjectEvaluationMetricsWidget';
import { ProjectIAAWidget } from 'src/modules/Analytic/components/ProjectIAAWidget';
import { IAADocumentationLink } from 'src/modules/Analytic/components/ProjectIAAWidget/IAADocumentationLink';
import { ProjectReportChip } from 'src/modules/Analytic/components/ProjectReportWidget/ProjectReportChip';
import { ProjectReportWidget } from 'src/modules/Analytic/components/ProjectReportWidget/ProjectReportWidget';
import {
  ProjectAnalyticsTab,
  TeamProjectAnalyticsPageFeatureTrackingName,
} from 'src/modules/Analytic/components/interfaces';
import { AnalyticFilterProvider } from 'src/modules/Analytic/context/AnalyticFilter';
import { EvaluationMetricsProvider } from 'src/modules/Analytic/context/EvaluationMetricsProvider';
import { ProjectContextProvider } from 'src/modules/Project/contexts/ProjectContext';
import { useActiveProject, useActiveProjectKinds } from 'src/modules/Project/hooks';
import { ChartLevel, ChartSet, IAAMethodName } from '../../../apps/common/__generated__/types';
import {
  EvaluationMetricLastUpdatedAtDate,
  IAALastUpdatedAtDate,
} from '../../../modules/Analytic/components/AnalyticsLastUpdatedAtDate';
import { useGetChartsQuery } from '../../../modules/Analytic/hooks/useGetChartsQuery';
import {
  MainLayoutBreadcrumb,
  MainLayoutBreadcrumbItemLink,
  MainLayoutBreadcrumbTitle,
  NavbarPortalGate,
} from '../MainLayout';
import { UserProfile } from '../MainLayout/UserProfile/UserProfile';
import { UserProfileMenuPortalGate } from '../MainLayout/UserProfile/UserProfileMenuPortal';
import { StyledTabs, TabsDivider } from '../TeamOverviewPage/TeamOverviewPage';

export default function TeamProjectAnalyticsPage() {
  const routeParams = useParams<{ teamId: string; projectId: string }>();

  return (
    <ProjectContextProvider projectId={routeParams.projectId}>
      {(projectContextValue) => {
        if (projectContextValue.loading) {
          return (
            <FlexBox height="100%" justifyContent="center" alignItems="center">
              <CircularProgress />
            </FlexBox>
          );
        }
        return <TeamProjectAnalyticsPageWrapper />;
      }}
    </ProjectContextProvider>
  );
}

function TeamProjectAnalyticsPageWrapper() {
  const team = useActiveTeam();
  const { formatMessage } = useIntl();
  const config = useConfig();
  const { push } = useHistory();
  const project = useActiveProject();
  const { hasLlmBased } = useActiveProjectKinds();
  const resolvedIntl = useIntlResolver({
    title: { message: project.name },
  });
  const { construct } = useRoute();
  const [displayedTab, setDisplayedTab] = useState(
    hasLlmBased ? ProjectAnalyticsTab.CHARTS : ProjectAnalyticsTab.PROJECT_REPORT,
  );
  const { trackEvent } = useFeatureTrackingService();

  const showElasticChart = getUrlParameter('showElasticCharts', Boolean, false);
  const defaultChartSet = config.app.defaultAnalyticsDatasource;
  // force elastic
  const chartSet = showElasticChart ? ChartSet.ELASTIC : defaultChartSet;
  const chartsQuery = useGetChartsQuery(team.id, ChartLevel.PROJECT, chartSet);

  const handleTabChange = useCallback((_event: React.SyntheticEvent, tab: ProjectAnalyticsTab) => {
    setDisplayedTab(tab);
  }, []);

  // IAA
  const [exportIAAToggle, _, enableExportIAA, disableExportIAA] = useToggle(false);
  const handleIAADataExists = (exists: boolean): void => (exists ? enableExportIAA : disableExportIAA)();
  const [calculationMethod, setCalculationMethod] = useState<IAAMethodName>(IAAMethodName.COHENS_KAPPA);

  const handleTrackFeature = useMemoizedCallback(
    (properties: FeatureTrackingProperties<TeamProjectAnalyticsPageFeatureTrackingName>): void => {
      trackEvent({
        action: FeatureTrackingAction.CLICK,
        properties,
      });
    },
  );

  const handleOnClickIAALink = useMemoizedCallback(() => {
    setDisplayedTab(ProjectAnalyticsTab.IAA);
    handleOnClickIAATab();
  });

  const handleOnClickIAATab = () => {
    handleTrackFeature({ name: TeamProjectAnalyticsPageFeatureTrackingName.CLICK_IAA_TAB });
  };

  const handleOnClickEvaluationMetricsTab = () => {
    handleTrackFeature({
      name: TeamProjectAnalyticsPageFeatureTrackingName.CLICK_EVALUATION_METRICS_TAB,
    });
  };

  function handleOpenProjectClick() {
    // always use review mode, because non-review mode won't work in archived projects.
    // context: https://datasaurlabels.slack.com/archives/CUZCPKVSN/p1741750804903139
    const link = construct(ROUTES.TEAM_WORKSPACE_REVIEW, { projectId: project?.id });
    push(link);
  }

  const breadcrumbItems = [
    {
      item: (
        <MainLayoutBreadcrumbItemLink to={construct(ROUTES.TEAM_PROJECTS)}>
          <FormattedMessage id="team-projects-page.title" />
        </MainLayoutBreadcrumbItemLink>
      ),
    },
    {
      item: (
        <MainLayoutBreadcrumbItemLink
          to={construct(project?.isArchived ? ROUTES.TEAM_PROJECTS_ARCHIVES : ROUTES.TEAM_PROJECTS)}
        >
          <FormattedMessage
            id={project?.isArchived ? 'team-projects-archives-page.title' : 'team.menu.projects-active'}
          />
        </MainLayoutBreadcrumbItemLink>
      ),
    },
    {
      item: <MainLayoutBreadcrumbTitle maxWidth="15vw">{resolvedIntl.title}</MainLayoutBreadcrumbTitle>,
    },
  ];

  return (
    <AnalyticFilterProvider>
      <EvaluationMetricsProvider projectId={project.id}>
        <WidgetsContainer p={3}>
          <NavbarPortalGate>
            <FlexBox ml={0}>
              <MainLayoutBreadcrumb breadcrumbItems={breadcrumbItems} />
            </FlexBox>

            <FlexBox ml={3}>
              {displayedTab === ProjectAnalyticsTab.PROJECT_REPORT && <ProjectReportChip status={project?.status} />}
              {displayedTab === ProjectAnalyticsTab.CHARTS && (
                <ChartsLastUpdatedAtDate
                  chartLevel={ChartLevel.PROJECT}
                  chartSet={chartSet}
                  input={{ teamId: team.id, projectId: project.id }}
                />
              )}
              {displayedTab === ProjectAnalyticsTab.IAA && (
                <IAALastUpdatedAtDate
                  teamId={team.id}
                  labelSetSignatures={[]}
                  projectId={project.id}
                  calculationMethod={calculationMethod}
                />
              )}
              {displayedTab === ProjectAnalyticsTab.EVALUATION_METRICS && <EvaluationMetricLastUpdatedAtDate />}
            </FlexBox>
          </NavbarPortalGate>
          <UserProfileMenuPortalGate>
            <UserProfile />
          </UserProfileMenuPortalGate>

          <Grid container>
            <Grid item xs={12}>
              <FlexBox justifyContent="space-between" alignItems="center">
                <StyledTabs value={displayedTab} onChange={handleTabChange}>
                  {!hasLlmBased && (
                    <Tabs.Tab
                      label={formatMessage({ id: 'team-project-analytics-page.title.project-report' })}
                      value={ProjectAnalyticsTab.PROJECT_REPORT}
                    />
                  )}
                  {config.app.featureToggle.enableAnalytics && (
                    <Tabs.Tab
                      label={formatMessage({ id: 'team-project-analytics-page.title.trends' })}
                      value={ProjectAnalyticsTab.CHARTS}
                    />
                  )}
                  <Tabs.Tab
                    label={formatMessage({ id: 'team-project-analytics-page.title.iaa' })}
                    value={ProjectAnalyticsTab.IAA}
                    onClick={handleOnClickIAATab}
                  />
                  <Tabs.Tab
                    label={formatMessage({ id: 'team-project-analytics-page.title.evaluation-metrics' })}
                    value={ProjectAnalyticsTab.EVALUATION_METRICS}
                    onClick={handleOnClickEvaluationMetricsTab}
                  />
                </StyledTabs>
                <OpenProjectButton variant="secondary" startIcon={<EditIcon />} onClick={handleOpenProjectClick}>
                  <FormattedMessage id="team-project-analytics-page.project-report.open-project" />
                </OpenProjectButton>
              </FlexBox>
              <TabsDivider />
            </Grid>

            {displayedTab === ProjectAnalyticsTab.CHARTS && (
              <Grid item xs={12}>
                <FlexBox mt={3} alignItems="center">
                  <AnalyticTrendsDateFilter />
                </FlexBox>
              </Grid>
            )}

            {displayedTab === ProjectAnalyticsTab.PROJECT_REPORT && (
              <Grid item md={12} xs={12}>
                <FlexBox p={3}>
                  <ProjectReportWidget onIAALinkClick={handleOnClickIAALink} />
                </FlexBox>
              </Grid>
            )}

            {displayedTab === ProjectAnalyticsTab.CHARTS && config.app.featureToggle.enableAnalytics && (
              <AnalyticChartsGrid
                chartsQuery={chartsQuery}
                widgetProps={{ teamId: team.id, projectId: project.id, height: 334 }}
              />
            )}

            {displayedTab === ProjectAnalyticsTab.IAA && (
              <IAAWidgetContainer>
                <IAAForm
                  teamId={team.id}
                  onSubmit={(data) => {
                    setCalculationMethod(data.calculationMethod);
                  }}
                  showProjectField={false}
                  showLabelSetField={false}
                  enableExportIAA={exportIAAToggle}
                  calculationMethod={calculationMethod}
                  projectId={project.id}
                />
                <ProjectIAAWidget
                  team={team}
                  labelSetSignatures={null}
                  projectId={project.id}
                  calculationMethod={calculationMethod}
                  onDataExists={handleIAADataExists}
                />
                <FlexBox mt={3}>
                  <IAADocumentationLink />
                </FlexBox>
              </IAAWidgetContainer>
            )}

            {displayedTab === ProjectAnalyticsTab.EVALUATION_METRICS && (
              <Grid item md={12} xs={12}>
                <FlexBox p={3}>
                  <ProjectEvaluationMetricsWidget />
                </FlexBox>
              </Grid>
            )}
          </Grid>
        </WidgetsContainer>
      </EvaluationMetricsProvider>
    </AnalyticFilterProvider>
  );
}

const WidgetsContainer = styled(FlexBox, { name: 'TeamProjectAnalyticsPage-WidgetsContainer' })({
  backgroundColor: 'white',
});

const OpenProjectButton = styled(Button, { name: 'TeamProjectAnalyticsPage-OpenProjectButton' })(({ theme }) => ({
  marginRight: theme.spacing(3),
}));

