import { PieChart } from '@vulcan-ai/frontend-shared/lib/src/commons/ui/components/PieChart';
import { SimpleXYChart } from '@vulcan-ai/frontend-shared/lib/src/commons/ui/components/SimpleXYChart';
import { ChartPaginationProvider } from '@vulcan-ai/frontend-shared/lib/src/commons/ui/components/SimpleXYChart/ChartPaginationProvider';
import { getAbbreviator } from '@vulcan-ai/frontend-shared/lib/src/commons/ui/components/SimpleXYChart/abbreviations/abbreviate';
import { styled } from '@vulcan-ai/vulcan-ui/lib/theme';
import React, { FC } from 'react';
import { ChartFragment, GetChartDataQuery, KeyPayloadType, Visualization } from 'src/apps/common/__generated__/types';
import { getDateRangeString } from '../../helper';
import { SimpleChartDataQueryHandler } from '../ChartDataQueryHandler';
import { AnalyticChartTable } from './AnalyticChartTable';
import { useAnalyticChartWidgetContext } from './AnalyticChartWidgetContext';
import { VisualizationMap } from './constants';
import { normalizeGqlLegend } from './helper';

export function AnalyticChart() {
  const {
    teamId,
    chart,
    projectId,
    userId,
    teamMemberId,
    labelType,
    dateRange,
    labeledBy,
    tagNames,
    hasTagFilter,
    setIsChartEmpty,
  } = useAnalyticChartWidgetContext();

  const calendarDate = getDateRangeString(dateRange);
  const { colors, pieHoleText, showTable } = chart.visualizationParams;

  return (
    <SimpleChartDataQueryHandler
      chartId={chart.id}
      teamId={teamId}
      projectId={projectId}
      userId={userId}
      teamMemberId={teamMemberId}
      calendarDate={calendarDate}
      labelType={labelType}
      labeledBy={labeledBy}
      tagNames={tagNames}
      hasTagFilter={hasTagFilter}
      setIsChartEmpty={setIsChartEmpty}
    >
      {(data: GetChartDataQuery, keyPayloadType: KeyPayloadType | undefined) => (
        <Container>
          {showTable ? (
            <ChartContainerWithTable>
              <SimpleChart
                chart={chart}
                colors={colors}
                data={data}
                pieHoleText={pieHoleText}
                keyPayloadType={keyPayloadType}
              />
            </ChartContainerWithTable>
          ) : (
            <ChartContainer>
              <SimpleChart
                chart={chart}
                colors={colors}
                data={data}
                pieHoleText={pieHoleText}
                keyPayloadType={keyPayloadType}
              />
            </ChartContainer>
          )}
          {showTable && (
            <TableContainer>
              <AnalyticChartTable headers={chart.dataTableHeaders} rows={data.result} />
            </TableContainer>
          )}
        </Container>
      )}
    </SimpleChartDataQueryHandler>
  );
}

interface SimpleChartProps extends PaginatedChartProps {
  colors: string[] | null;
  pieHoleText: string | null;
}

const SimpleChart: FC<SimpleChartProps> = ({ chart, data, colors, pieHoleText, keyPayloadType }) => {
  if (chart.visualizationParams.visualization === Visualization.PIE_CHART) {
    return (
      <PieChartContainer>
        <PieChart
          data={[
            [...chart.dataTableHeaders],
            ...data.result.map((row) => [row.key, ...row.values.map((v) => parseFloat(v.value))]),
          ]}
          colors={colors ?? undefined}
          pieHole={0.8}
          pieHoleText={pieHoleText ?? undefined}
        />
      </PieChartContainer>
    );
  }
  return <PaginatedChart chart={chart} data={data} keyPayloadType={keyPayloadType} />;
};

interface PaginatedChartProps {
  chart: ChartFragment;
  data: GetChartDataQuery;
  keyPayloadType?: KeyPayloadType;
}

const PaginatedChart: FC<PaginatedChartProps> = ({ chart, data, keyPayloadType }) => {
  const {
    chartArea,
    colorGradient,
    colors,
    hAxisTitle,
    isStacked,
    itemsPerPage,
    legend,
    unit,
    vAxisTitle,
    visualization,
  } = chart.visualizationParams;

  return (
    <ChartPaginationProvider
      headers={chart.dataTableHeaders}
      data={[...data.result.map((row) => [row.key, ...row.values.map((v) => parseFloat(v.value))])]}
      itemsPerPage={itemsPerPage ?? undefined}
    >
      <SimpleXYChart
        chartType={VisualizationMap[visualization]}
        abbreviator={getAbbreviator(keyPayloadType)}
        chartArea={chartArea ?? undefined}
        colorGradient={colorGradient ?? undefined}
        colors={colors ?? undefined}
        hAxisTitle={hAxisTitle ?? undefined}
        isStacked={isStacked ?? undefined}
        legend={normalizeGqlLegend(legend ?? undefined)}
        unit={unit ?? undefined}
        vAxisTitle={vAxisTitle ?? undefined}
      />
    </ChartPaginationProvider>
  );
};

const ChartContainer = styled('div', { name: 'AnalyticChart-ChartContainer' })({
  height: '100%',
});

const ChartContainerWithTable = styled('div', { name: 'AnalyticChart-ChartContainerWithTable' })({
  height: '50%',
  overflowY: 'auto',
  overflowX: 'hidden',
});

const Container = styled('div', { name: 'AnalyticChart-Container' })({
  height: '100%',
});

const PieChartContainer = styled('div', { name: 'AnalyticChart-PieChartContainer' })(({ theme }) => ({
  flex: 1,
  marginTop: theme.spacing(4),
}));

const TableContainer = styled('div', { name: 'AnalyticChart-TableContainer' })({
  height: '50%',
  overflowY: 'auto',
  overflowX: 'hidden',
});

