import { DateRange } from '@vulcan-ai/frontend-shared/lib/src/commons/form/fields/DateRange/interfaces';
import { Paper } from '@vulcan-ai/vulcan-ui/lib/components/Paper';
import { excludeForwardProps } from '@vulcan-ai/vulcan-ui/lib/helpers/excludeForwardProps';
import { styled } from '@vulcan-ai/vulcan-ui/lib/theme';
import React, { useMemo, useState } from 'react';
import { AnalyticsLabelType, ChartFragment, Role } from 'src/apps/common/__generated__/types';
import { AnalyticChartWidgetContent } from './AnalyticChartWidgetContent';
import { AnalyticChartWidgetContext, AnalyticChartWidgetContextValue } from './AnalyticChartWidgetContext';

export interface AnalyticChartWidgetProps {
  dateRange: DateRange;
  teamId: string;
  chart: ChartFragment;
  height: number;
  projectId?: string;
  userId?: string | null;
  teamMemberId?: string;
  labelType?: AnalyticsLabelType;
  labeledBy?: Role;
  tagNames?: string[];
  hasTagFilter?: boolean;
}

export function AnalyticChartWidget({
  dateRange,
  teamId,
  chart,
  height,
  projectId,
  userId,
  teamMemberId,
  labelType,
  labeledBy,
  tagNames,
  hasTagFilter,
}: AnalyticChartWidgetProps) {
  const [isChartEmpty, setIsChartEmpty] = useState(false);
  const contextValue: AnalyticChartWidgetContextValue = useMemo(
    () => ({
      dateRange,
      teamId,
      chart,
      projectId,
      userId,
      teamMemberId,
      labelType,
