import { InfoOutlineIcon } from '@vulcan-ai/vulcan-ui/lib/icon/InfoOutlineIcon';
import { styled } from '@vulcan-ai/vulcan-ui/lib/theme';
import React from 'react';
import { FormattedMessage } from 'react-intl';
import { ExportChartQuery, ExportChartQueryVariables } from 'src/apps/common/__generated__/types';
import { getDateRangeString } from '../../helper';
import { useExportChartQueryFunction } from '../../hooks/useExportChartQueryFunction';
import { isThroughputChart } from '../ChartDataQueryHandler/isThroughputChart';
import { AnalyticChart } from './AnalyticChart';
import { useAnalyticChartWidgetContext } from './AnalyticChartWidgetContext';

export function AnalyticChartWidgetContent() {
  const context = useAnalyticChartWidgetContext();
  const { dateRange, chart, teamId, projectId, userId, teamMemberId, labelType, labeledBy, tagNames, isChartEmpty } =
    context;
  const exportChartFunction: (variables: ExportChartQueryVariables) => Promise<ApolloQueryResult<ExportChartQuery>> =
    useExportChartQueryFunction();

  const dialog = useDialog();
  const { trackEvent } = useFeatureTrackingService();
  const calendarDate = getDateRangeString(dateRange);

  const handleExport = useHandler(async () => {
    trackEvent({
      action: FeatureTrackingAction.CLICK,
      properties: {
        name: AnalyticChartWidgetContentFeatureTrackingName.EXPORT_ANALYTICS_CHART,
        description: chart.name,
      },
    });
    await exportChartFunction({
      id: chart.id,
      input: {
        teamId,
        calendarDate,
        projectId,
        userId,
        teamMemberId,
        labelType,
        // TODO: Remove exceptions like this and make a more robust parameter
        labeledBy: isThroughputChart(chart.id) ? labeledBy : undefined,
        tagNames,
      },
    });
    await dialog.alert(<FormattedMessage id="analytic.export-chart-success" />);
    // context is memoized upstream over exactly these fields (see AnalyticChartWidget.tsx),
    // so depending on it as a whole covers every field the closure reads above.
  }, [context, exportChartFunction, dialog, trackEvent]);

  return (
    <FlexBox direction="column" fullHeight>
      <FlexBox>
        <FlexBox alignItems="flex-start" justifyContent="center">
          <Typography variant="subtitle2">{chart.name}</Typography>
          <TooltipContainer>
            <Tooltip title={chart.description} arrow placement="right">
              <InfoOutlineIcon />
            </Tooltip>
          </TooltipContainer>
        </FlexBox>

        <ChartActions alignItems="center" justifyContent="flex-end">
          <ChartButton variant="tertiary" size="small" onClick={handleExport} disabled={isChartEmpty}>
            <ImportIcon color="primary" height={20} width={20} />
          </ChartButton>
        </ChartActions>
      </FlexBox>

      <ChartContainer>
        <AnalyticChart />
      </ChartContainer>
    </FlexBox>
  );
}

const enum AnalyticChartWidgetContentFeatureTrackingName {
  EXPORT_ANALYTICS_CHART = 'export an analytics chart',
}

const ChartActions = styled(FlexBox, { name: 'AnalyticChartWidgetContent-ChartActions' })(({ theme }) => ({
  flex: 1,
  '& > div:not(:first-child)': {
    marginLeft: theme.spacing(2),
  },
}));

const ChartButton = styled(Button, { name: 'AnalyticChartWidgetContent-ChartButton' })({
  height: 30,
  width: 30,
});

const ChartContainer = styled('div', { name: 'AnalyticChartWidgetContent-ChartContainer' })({
  flex: 1,
  overflow: 'hidden',
});

const TooltipContainer = styled('div', { name: 'AnalyticChartWidgetContent-TooltipContainer' })(({ theme }) => ({
  lineHeight: 1.43,
  marginLeft: theme.spacing(1),
}));

