import { useConfig } from '@vulcan-ai/frontend-shared/lib/src/commons/config';
import { DateRangeSelectField } from '@vulcan-ai/frontend-shared/lib/src/commons/form/fields/DateRange/DateRangeSelectField';
import { DateRangeMode } from '@vulcan-ai/frontend-shared/lib/src/commons/form/fields/DateRange/interfaces';
import { DocumentationLink } from '@vulcan-ai/frontend-shared/lib/src/modules/Documentation/components/DocumentationLink';
import { DocumentationPath } from '@vulcan-ai/frontend-shared/lib/src/modules/Documentation/constants';
import { Box } from '@vulcan-ai/vulcan-ui/lib/components/Box/Box';
import { Divider } from '@vulcan-ai/vulcan-ui/lib/components/Divider/Divider';
import { FlexBox } from '@vulcan-ai/vulcan-ui/lib/components/Flex/FlexBox';
import { DateField as _DateField } from '@vulcan-ai/vulcan-ui/lib/components/Form/fields/DateField/DateField';
import { useWatchValue } from '@vulcan-ai/vulcan-ui/lib/components/Form/helpers/useWatchValue';
import { Tooltip } from '@vulcan-ai/vulcan-ui/lib/components/Tooltip/Tooltip';
import { Typography } from '@vulcan-ai/vulcan-ui/lib/components/Typography';
import { InfoOutlineIcon } from '@vulcan-ai/vulcan-ui/lib/icon/InfoOutlineIcon';
import { styled } from '@vulcan-ai/vulcan-ui/lib/theme';
import React, { useEffect, useMemo } from 'react';
import { useFormContext } from 'react-hook-form';
import { FormattedMessage, useIntl } from 'react-intl';
import {
  getAdjustedEndDate,
  getAnalyticsDataRetentionMonths,
  getMaxEndDate,
  getMaximumAnalyticsDateRange,
  getMinEndDate,
  getMinimumAnalyticsDate,
} from '../helper';

export function AnalyticTrendsDateFilter() {
  const config = useConfig();
  const { formatMessage } = useIntl();
  const { setValue } = useFormContext();
  const dateRangeMode = useWatchValue('dateRange.mode', 'field-level', []);
  const startDate = useWatchValue('dateRange.startDate', 'field-level', []);
  const endDate = useWatchValue('dateRange.endDate', 'field-level', []);

  const minimumAnalyticsDate = getMinimumAnalyticsDate(config.app.analyticsDataRetentionMonths);
  const maximumAnalyticsDateRange = getMaximumAnalyticsDateRange(config.app.analyticsMaximumDateRange);
  const analyticsDataRetentionMonths = getAnalyticsDataRetentionMonths(config.app.analyticsDataRetentionMonths);

  const maxEndDate = useMemo(
    () => getMaxEndDate(startDate, maximumAnalyticsDateRange),
    [startDate, maximumAnalyticsDateRange],
  );

  const minEndDate = useMemo(() => getMinEndDate(startDate), [startDate]);

  // Automatically adjust end date if needed
  useEffect(() => {
    if (startDate && endDate && dateRangeMode === DateRangeMode.CUSTOM) {
      const adjustedEndDate = getAdjustedEndDate(startDate, endDate, maximumAnalyticsDateRange);
      if (adjustedEndDate) {
        setValue('dateRange.endDate', adjustedEndDate);
      }
    }
  }, [startDate, endDate, dateRangeMode, maximumAnalyticsDateRange, setValue]);

  return (
    <FlexBox px={3} gap={2} direction="row" alignItems="flex-end" justifyContent="space-between" fullWidth>
      <FlexBox gap={2} direction="row" alignItems="center">
        <Title variant="body1" fontWeight="bold" mr={2}>
          <FormattedMessage id="team-overview-page.trends" />
        </Title>
        <TooltipContainer>
          <Tooltip
            title={formatMessage(
              { id: 'team-overview-page.trends.tooltip' },
              { days: maximumAnalyticsDateRange, months: analyticsDataRetentionMonths },
            )}
            arrow
            placement="top-end"
          >
            <InfoOutlineIcon />
          </Tooltip>
        </TooltipContainer>
        <DocumentationLink documentationPath={DocumentationPath.PROJECT_ANALYTICS}>
          <FormattedMessage id="team-overview-page.trends.learn-more" />
        </DocumentationLink>
      </FlexBox>
      <FlexBox gap={2}>
        <DateRangeSelectField
          name="dateRange"
          label={formatMessage({ id: 'team-member-analytics.date-range.label' })}
          width={160}
        />
        <DividerMargin>
          <Divider orientation="vertical" />
        </DividerMargin>
        <Box>
          <DateField
            name="dateRange.startDate"
            minDate={minimumAnalyticsDate}
            maxDate={new Date()}
            inputFormat="MMM dd, yyyy"
            disabled={dateRangeMode !== DateRangeMode.CUSTOM}
            label={formatMessage({ id: 'team-member-analytics.date-range.start-date.label' })}
          />
        </Box>
        <Box>
          <DateField
            name="dateRange.endDate"
            minDate={minEndDate}
            maxDate={maxEndDate}
            inputFormat="MMM dd, yyyy"
            disabled={dateRangeMode !== DateRangeMode.CUSTOM}
            label={formatMessage({ id: 'team-member-analytics.date-range.end-date.label' })}
          />
        </Box>
      </FlexBox>
    </FlexBox>
  );
}

const Title = styled(Typography, { name: 'AnalyticTrendsDateFilter-Title' })({
  margin: '4px 0',
});

const DividerMargin = styled(Box, { name: 'AnalyticTrendsDateFilter-DividerMargin' })({
  margin: '24px 8px 0',
});

const DateField = styled(_DateField, { name: 'AnalyticTrendsDateFilter-DateField' })({
  marginBottom: 0,
  width: 160,
});

const TooltipContainer = styled(FlexBox, { name: 'AnalyticTrendsDateFilter-TooltipContainer' })({
  lineHeight: 1.43,
});

