import { QueryResult } from '@apollo/client';
import React, { ReactNode } from 'react';

import {
  AnalyticsLabelType,
  GetChartDataQuery,
  GetChartDataQueryVariables,
  KeyPayloadType,
  Role,
} from '../../../../apps/common/__generated__/types';
import { useGetChartDataQuery } from '../../hooks/useGetChartDataQuery';
import { ChartDataQueryHandler } from './ChartDataQueryHandler';
import { isThroughputChart } from './isThroughputChart';

interface Props {
  chartId: string;
  teamId: string;
  children: (data: GetChartDataQuery, keyPayloadType?: KeyPayloadType) => ReactNode;

  projectId?: string;
  userId?: string | null;
  teamMemberId?: string;
  labelType?: AnalyticsLabelType;
  calendarDate?: string;
  labeledBy?: Role;
  tagNames?: string[];
  hasTagFilter?: boolean;

  setIsChartEmpty: (isChartEmpty: boolean) => void;
}

export function SimpleChartDataQueryHandler({
  chartId,
  teamId,
  children,
  projectId,
  userId,
  teamMemberId,
  labelType,
  calendarDate,
  labeledBy,
  tagNames,
  hasTagFilter,
  setIsChartEmpty,
}: Readonly<Props>) {
  const input = {
    teamId,
    projectId,
    userId,
    teamMemberId,
    labelType,
    calendarDate,
    labeledBy: isThroughputChart(chartId) ? labeledBy : undefined,
    tagNames,
  };
  const chartDataQueryResult: QueryResult<GetChartDataQuery, GetChartDataQueryVariables> = useGetChartDataQuery(
    chartId,
    input,
  );

  return (
    <ChartDataQueryHandler
      chartId={chartId}
      chartDataQueryResult={chartDataQueryResult}
      setIsChartEmpty={setIsChartEmpty}
      hasTagFilter={hasTagFilter}
    >
      {children}
    </ChartDataQueryHandler>
  );
}

