import { getStartAndEndDate } from '@vulcan-ai/frontend-shared/lib/src/commons/form/fields/DateRange/helper';
import { DateRangeMode } from '@vulcan-ai/frontend-shared/lib/src/commons/form/fields/DateRange/interfaces';
import { FlexBox } from '@vulcan-ai/vulcan-ui/lib/components/Flex/FlexBox';
import { Form } from '@vulcan-ai/vulcan-ui/lib/components/Form/Form';
import { styled } from '@vulcan-ai/vulcan-ui/lib/theme';
import React, { FC } from 'react';
import { AnalyticFilterContextValue } from './interfaces';

export const AnalyticFilterProvider: FC = ({ children }) => {
  const defaultDateRangeMode = DateRangeMode.LAST_7_DAYS;
  const defaultDateRange = getStartAndEndDate(defaultDateRangeMode);

  return (
    <FormContainer direction="column" fullHeight>
      <Form<AnalyticFilterContextValue>
        defaultValues={{
          dateRange: { mode: defaultDateRangeMode, ...defaultDateRange },
          projectKind: undefined,
          tagNames: [],
        }}
        onSubmitValid={() => void 0}
      >
        {children}
      </Form>
    </FormContainer>
  );
};

const FormContainer = styled(FlexBox, { name: 'AnalyticsFilterProviderFormContainer' })(() => ({
  backgroundColor: 'white',
  overflow: 'auto',
}));

