import { QueryResult } from '@apollo/client';
import { PieChart } from '@vulcan-ai/frontend-shared/lib/src/commons/ui/components/PieChart';
import { DataTable } from '@vulcan-ai/frontend-shared/lib/src/commons/ui/components/SimpleXYChart';
import { Button } from '@vulcan-ai/vulcan-ui/lib/components/Button/Button';
import { FlexBox } from '@vulcan-ai/vulcan-ui/lib/components/Flex/FlexBox';
import { Paper } from '@vulcan-ai/vulcan-ui/lib/components/Paper';
import { Tooltip } from '@vulcan-ai/vulcan-ui/lib/components/Tooltip/Tooltip';
import { Typography } from '@vulcan-ai/vulcan-ui/lib/components/Typography';
import { excludeForwardProps } from '@vulcan-ai/vulcan-ui/lib/helpers/excludeForwardProps';
import { DownloadIcon } from '@vulcan-ai/vulcan-ui/lib/icon/DownloadIcon';
import { InfoOutlineIcon } from '@vulcan-ai/vulcan-ui/lib/icon/InfoOutlineIcon';
import { styled } from '@vulcan-ai/vulcan-ui/lib/theme';
import React from 'react';
import { EmptyStatisticalAnalyticsData } from './EmptyStatisticalAnalyticsData';
import { StatisticalAnalyticChartDataQueryHandler } from './StatisticalAnalyticChartDataQueryHandler';

interface Props<T> {
  name: string;
  description: string;
  colors: string[];
  pieHoleText: string;
  dataTransformer: (data: T) => DataTable;
  emptyDataValidator: (data: T) => boolean;
  query: (teamId: string, tagNames: string[]) => QueryResult<T>;
  handleExport?: () => void;
}

export function StatisticalAnalyticChartWidget<T>({
  name,
  description,
  colors,
  pieHoleText,
  dataTransformer,
  emptyDataValidator,
  query,
  handleExport,
}: Readonly<Props<T>>) {
  return (
    <StyledPaper height={334} elevation={0}>
      <FlexBox direction="column" fullHeight>
        <ChartHeader>
          <ChartTitle>
            <Typography variant="subtitle2">{name}</Typography>
            <TooltipContainer>
              <Tooltip title={description} arrow placement="right">
                <InfoOutlineIcon />
              </Tooltip>
            </TooltipContainer>
          </ChartTitle>

          {handleExport && (
            <ChartActions>
              <ChartButton variant="tertiary" size="small" onClick={handleExport}>
                <DownloadIcon color="primary" />
              </ChartButton>
            </ChartActions>
          )}
        </ChartHeader>

        <ChartBody>
          <StatisticalAnalyticChartDataQueryHandler query={query}>
            {(data) =>
              emptyDataValidator(data) ? (
                <EmptyStatisticalAnalyticsData />
              ) : (
                <Container>
                  <PieChartContainer>
                    <PieChart data={dataTransformer(data)} colors={colors} pieHole={0.8} pieHoleText={pieHoleText} />
                  </PieChartContainer>
                </Container>
              )
            }
          </StatisticalAnalyticChartDataQueryHandler>
        </ChartBody>
      </FlexBox>
    </StyledPaper>
  );
}

const ChartActions = styled('div', { name: 'StatisticalAnalyticChartWidget-ChartActions' })(({ theme }) => ({
  alignItems: 'center',
  display: 'flex',
  flex: 1,
  justifyContent: 'flex-end',
  '& > div:not(:first-child)': {
    marginLeft: theme.spacing(2),
  },
}));

const ChartBody = styled('div', { name: 'StatisticalAnalyticChartWidget-ChartBody' })({
  flex: 1,
  overflow: 'hidden',
});

const ChartButton = styled(Button, { name: 'StatisticalAnalyticChartWidget-ChartButton' })({
  height: 30,
  width: 30,
});

const ChartHeader = styled('div', { name: 'StatisticalAnalyticChartWidget-ChartHeader' })({
  display: 'flex',
});

const ChartTitle = styled('div', { name: 'StatisticalAnalyticChartWidget-ChartTitle' })({
  alignItems: 'flex-start',
  display: 'flex',
  justifyContent: 'center',
});

const Container = styled('div', { name: 'StatisticalAnalyticChartWidget-Container' })({
  height: '100%',
});

const PieChartContainer = styled('div', { name: 'StatisticalAnalyticChartWidget-PieChartContainer' })(({ theme }) => ({
  flex: 1,
  marginTop: theme.spacing(4),
}));

const StyledPaper = styled(Paper, {
  name: 'StatisticalAnalyticChartWidget-Paper',
  shouldForwardProp: excludeForwardProps(['height']),
})<{ height: number }>(({ height, theme }) => ({
  border: `1px solid ${theme.palette.lightGrey2}`,
  borderRadius: 8,
  height,
  padding: theme.spacing(3),
}));

const TooltipContainer = styled('div', { name: 'StatisticalAnalyticChartWidget-TooltipContainer' })(({ theme }) => ({
  lineHeight: 1.43,
  marginLeft: theme.spacing(1),
}));

