import { DropdownField as _DropdownField } from '@vulcan-ai/vulcan-ui/lib/components/Form/fields/DropdownField/DropdownField';
import { DropdownOption } from '@vulcan-ai/vulcan-ui/lib/components/Form/fields/DropdownField/interfaces';
import { ValueAdapter } from '@vulcan-ai/vulcan-ui/lib/components/Form/helpers/ValueAdapter/interfaces';
import { styled, theme } from '@vulcan-ai/vulcan-ui/lib/theme';
import React, { useMemo } from 'react';
import { useIntl } from 'react-intl';
import { Tag } from 'src/apps/common/__generated__/types';
import { useGetTagsQuery } from 'src/modules/Tag/hooks';
import { CustomPopper } from '../CustomPopper';

interface AnalyticTagDropdownFieldProps {
  name: string;
  teamId?: string;
}

const convertToDropdownOption = (tag: Tag) => ({
  id: tag.id,
  label: tag.name,
});

export function AnalyticTagDropdownField({ name, teamId }: Readonly<AnalyticTagDropdownFieldProps>) {
  const { formatMessage } = useIntl();

  const { data } = useGetTagsQuery(teamId);
  const tags = data?.tags ?? [];

  const tagOptions = useMemo(() => tags.map(convertToDropdownOption), [tags]);

  const valueAdapter: ValueAdapter<DropdownOption, string> = useMemo(
    () => ({
      toTargetValue: (displayValue: DropdownOption) => {
        return displayValue.label;
      },
      toDisplayValue: (targetValue: string) => {
        return {
          id: tagOptions?.find((tag) => tag.label === targetValue)?.id ?? '',
          label: targetValue,
        };
      },
    }),
    [tagOptions],
  );

  return (
    <DropdownField
      placeholder={formatMessage({ id: 'analytic.filter.tags.select' })}
      options={tagOptions}
      label={formatMessage({ id: 'analytic.filter.tags.label' })}
      multiple
      checkbox
      name={name}
      valueAdapter={valueAdapter}
      fullWidth
      PopperComponent={CustomPopper}
    />
  );
}

const DropdownField = styled(_DropdownField, { name: 'AnalyticTagFilterWidget-DropdownFieldUI' })({
  marginBottom: `-${theme.spacing(3)}`,
});

